package cz.mh.rallye.rallye_backend.templates;
import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;import org.springframework.context.annotation.Import;import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.test.web.servlet.MockMvc;import org.springframework.mock.web.MockMultipartFile;import jakarta.servlet.http.Cookie;
import cz.mh.rallye.rallye_backend.templates.api.TemplateTransferController;import cz.mh.rallye.rallye_backend.templates.application.*;import cz.mh.rallye.rallye_backend.identity.api.*;import cz.mh.rallye.rallye_backend.identity.application.*;
import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.csrf;
@WebMvcTest(TemplateTransferController.class) @Import({AuthConfiguration.class,AuthCookies.class,ApiErrors.class})
class TemplateTransferHttpTest {
 @Autowired MockMvc mvc;@MockitoBean AuthService auth;@MockitoBean TemplateTransferService service;
 final UUID id=UUID.randomUUID();final String secret=new SecretTokens().create();final AuthService.Principal actor=new AuthService.Principal(UUID.randomUUID(),UUID.randomUUID(),false);final String base="/api/v1/race-templates";
 void login(boolean admin){when(auth.authenticate(secret)).thenReturn(actor);when(auth.isAdministrator(actor)).thenReturn(admin);}
 MockMultipartFile file(){return new MockMultipartFile("file","archive.zip","application/zip",new byte[]{1});}
 @Test void allEndpointsRequireAdmin()throws Exception{mvc.perform(get(base+"/"+id+"/export")).andExpect(status().isUnauthorized());login(false);mvc.perform(get(base+"/"+id+"/export").header("Authorization","Bearer "+secret)).andExpect(status().isForbidden());mvc.perform(multipart(base+"/imports/preview").file(file()).header("Authorization","Bearer "+secret)).andExpect(status().isForbidden());mvc.perform(multipart(base+"/imports").file(file()).header("Authorization","Bearer "+secret).header("Idempotency-Key",UUID.randomUUID())).andExpect(status().isForbidden());verifyNoInteractions(service);}
 @Test void exportIsPrivateZipAttachment()throws Exception{login(true);when(service.export(actor,id)).thenReturn(new byte[]{1,2});mvc.perform(get(base+"/"+id+"/export").header("Authorization","Bearer "+secret)).andExpect(status().isOk()).andExpect(content().contentType("application/zip")).andExpect(header().string("Cache-Control","no-store")).andExpect(header().string("Content-Disposition","attachment; filename=\"rallye-template.zip\"")).andExpect(header().string("X-Content-Type-Options","nosniff")).andExpect(content().bytes(new byte[]{1,2}));}
 @Test void previewDoesNotImportAndCookieStillRequiresCsrf()throws Exception{login(true);when(service.preview(eq(actor),any())).thenReturn(new TemplateArchive.Preview("Preview",2,3,List.of("IMPORTED_AS_DRAFT")));mvc.perform(multipart(base+"/imports/preview").file(file()).cookie(new Cookie(AuthCookies.NAME,secret))).andExpect(status().isForbidden());mvc.perform(multipart(base+"/imports/preview").file(file()).cookie(new Cookie(AuthCookies.NAME,secret)).with(csrf().asHeader())).andExpect(status().isOk()).andExpect(jsonPath("$.stageCount").value(2)).andExpect(jsonPath("$.fileCount").value(3));verify(service,never()).importTemplate(any(),any(),any());}
 @Test void importRequiresKeyAndReturnsCreatedLocation()throws Exception{login(true);mvc.perform(multipart(base+"/imports").file(file()).header("Authorization","Bearer "+secret)).andExpect(status().isBadRequest());when(service.importTemplate(eq(actor),any(),any())).thenReturn(new TemplateService.Created(id,id,0));mvc.perform(multipart(base+"/imports").file(file()).header("Authorization","Bearer "+secret).header("Idempotency-Key",UUID.randomUUID())).andExpect(status().isCreated()).andExpect(header().string("Location",base+"/"+id)).andExpect(jsonPath("$.id").value(id.toString())).andExpect(jsonPath("$.version").value(0));}
}
